window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-476624f13d373fe0"]={"versions": [{"id": "FIG-476624f13d373fe0", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Aktivitätsdiagramm (SPEM-/UML-basiert) zur Spezifikation von BSW-Moduldefinitionen im Rahmen des Classic-Platform-Entwicklungsprozesses. Es beschreibt den methodischen Schritt der herstellerspezifischen Anpassung und Ergänzung standardisierter Parameterdefinitionen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Rollen</strong>:</li>\n<li><code>Basic Software Designer</code> (Kardinalität <code>0..1</code>, Assoziation <code>«performs»</code>)</li>\n<li><code>Basic Software Module Developer</code> (Kardinalität <code>0..1</code>, Assoziation <code>«performs»</code>)</li>\n<li><strong>Aktivität</strong>:</li>\n<li><code>Define Vendor Specific Module Definition</code> (zentraler Prozessschritt)</li>\n<li><strong>Artefakte und Schnittstellen</strong>:</li>\n<li><code>AUTOSAR Standardized ECU Configuration Parameter Definition</code> (Eingangsartefakt, Beziehung <code>«input»</code>, Kardinalität <code>1</code>)</li>\n<li><code>BSW Module Vendor Specific Parameter Definition</code> (Ausgangsartefakt, rechts abgeschnitten als <code>BSW Module Ven...</code>, Beziehung <code>«output»</code>, Kardinalität <code>1</code>)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Das standardisierte Eingangsartefakt <code>AUTOSAR Standardized ECU Configuration Parameter Definition</code> wird bereitgestellt.</li>\n<li>Mindestens eine der beteiligten Rollen (<code>Basic Software Designer</code> oder <code>Basic Software Module Developer</code>) führt die Aktivität <code>Define Vendor Specific Module Definition</code> durch.</li>\n<li>Als Ergebnis der Aktivität wird genau eine Instanz der <code>BSW Module Vendor Specific Parameter Definition</code> erzeugt.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Aktivität ist normativ für BSW-Zulieferer und -Entwickler, um standardisierte ECU-Konfigurationsparameter um herstellerspezifische Parameter, Konfigurationsklassen und Moduldefinitionen zu erweitern. Das erzeugte Artefakt bildet die formale Grundlage für nachgelagerte Schritte der BSW-Generierung und -Konfiguration.</p>"}, {"id": "FIG-a8d6a7b0f4c170e2", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Aktivitätsdiagramm (SPEM-/UML-basiert) zur Spezifikation von BSW-Moduldefinitionen im Rahmen des Classic-Platform-Entwicklungsprozesses. Es beschreibt den methodischen Schritt der herstellerspezifischen Anpassung und Ergänzung standardisierter Parameterdefinitionen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Rollen</strong>:</li>\n<li><code>Basic Software Designer</code> (Kardinalität <code>0..1</code>, Assoziation <code>«performs»</code>)</li>\n<li><code>Basic Software Module Developer</code> (Kardinalität <code>0..1</code>, Assoziation <code>«performs»</code>)</li>\n<li><strong>Aktivität</strong>:</li>\n<li><code>Define Vendor Specific Module Definition</code> (zentraler Prozessschritt)</li>\n<li><strong>Artefakte und Schnittstellen</strong>:</li>\n<li><code>AUTOSAR Standardized ECU Configuration Parameter Definition</code> (Eingangsartefakt, Beziehung <code>«input»</code>, Kardinalität <code>1</code>)</li>\n<li><code>BSW Module Vendor Specific Parameter Definition</code> (Ausgangsartefakt, rechts abgeschnitten als <code>BSW Module Ven...</code>, Beziehung <code>«output»</code>, Kardinalität <code>1</code>)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Das standardisierte Eingangsartefakt <code>AUTOSAR Standardized ECU Configuration Parameter Definition</code> wird bereitgestellt.</li>\n<li>Mindestens eine der beteiligten Rollen (<code>Basic Software Designer</code> oder <code>Basic Software Module Developer</code>) führt die Aktivität <code>Define Vendor Specific Module Definition</code> durch.</li>\n<li>Als Ergebnis der Aktivität wird genau eine Instanz der <code>BSW Module Vendor Specific Parameter Definition</code> erzeugt.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Aktivität ist normativ für BSW-Zulieferer und -Entwickler, um standardisierte ECU-Konfigurationsparameter um herstellerspezifische Parameter, Konfigurationsklassen und Moduldefinitionen zu erweitern. Das erzeugte Artefakt bildet die formale Grundlage für nachgelagerte Schritte der BSW-Generierung und -Konfiguration.</p>"}], "trans": [{"from": "FIG-476624f13d373fe0", "to": "FIG-a8d6a7b0f4c170e2", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
